from __future__ import annotations
import cmath

def spike_value(location: int, s: complex) -> complex:
    return cmath.exp(-s * cmath.log(location))

def demonstrate(cutoff: int, s: complex = 2 + 0j) -> None:
    if cutoff < 0:
        raise ValueError("cutoff must be nonnegative")
    a, b = cutoff + 1, cutoff + 2
    print(f"Both sequences vanish through index {cutoff}.")
    print(f"Their supports are {a} and {b}.")
    print(f"Values: {spike_value(a, s)} and {spike_value(b, s)}")
    print(f"Difference: {abs(spike_value(a, s)-spike_value(b, s))}")

if __name__ == "__main__":
    demonstrate(20)

from __future__ import annotations

def phi(n: int) -> int:
    if n <= 0:
        raise ValueError("n must be positive")
    result, remainder, p = n, n, 2
    while p * p <= remainder:
        if remainder % p == 0:
            while remainder % p == 0:
                remainder //= p
            result -= result // p
        p += 1
    if remainder > 1:
        result -= result // remainder
    return result

def table(limit: int) -> list[tuple[int, int]]:
    return [(q, phi(q)) for q in range(1, limit + 1)]

if __name__ == "__main__":
    for q, count in table(30):
        print(f"modulus {q:2d}: {count:2d} characters")

from __future__ import annotations
from math import gcd

def phi(n: int) -> int:
    return sum(1 for a in range(1, n + 1) if gcd(a, n) == 1)

def audit(m: int, k: int) -> dict[str, int | bool]:
    if m <= 0 or k <= 0:
        raise ValueError("moduli must be positive")
    return {"coprime": gcd(m, k) == 1,
            "combined": phi(m * k),
            "product": phi(m) * phi(k)}

if __name__ == "__main__":
    for pair in [(5, 8), (7, 9), (4, 2), (12, 25)]:
        print(pair, audit(*pair))

