    q = list(range(1, limit + 1)); counts = [phi(n) for n in q]
    plt.bar(q, counts, width=.85, color="#4c78a8")
    plt.xlabel("modulus q"); plt.ylabel("number of characters φ(q)")
    plt.title("Finite Dirichlet L-Function Families at Fixed Modulus")
    plt.tight_layout(); plt.savefig("dirichlet_character_census.png", dpi=180)
if __name__ == "__main__": plot()

